// `npm run run -- story <topic> <story-id> --fresh` (spec §5.8): the fixture story's production folder is archived
// whole to topics/<topic>/history/<run id>/ (gitignored) and every stage runs again through the real pipeline: new
// artifacts, new fingerprints, new approvals, a new upload. Nothing is copied back. Refused for any topic that is not
// a fixture topic (`commissions[key].fixtureTopics`): ordinary stories are never regenerated by a flag.
import { existsSync, mkdirSync, readdirSync, renameSync } from 'node:fs';
import { join } from 'node:path';
import { isFixtureTopic } from '../../config/site';
import { ROOT, readJson, scriptDir, topicDir, writeJsonAtomic } from '../../shared/io';
import { Refusal } from '../../shared/refusal';
import type { FreshRun } from '../../shared/types';
import { FRESH_FILE } from '../../shared/types';
import { RUN_DIR, runDir } from './journal';
import { readLock } from './lock';
import { alive } from './proc';

export const HISTORY_DIR = 'history';

/** `YYYYMMDD-hhmm-<4 hex>`: names the archive, the journal, the video title and the manifest. */
export function freshRunId(now = new Date()): string {
  const p = (n: number) => String(n).padStart(2, '0');
  const hex = Math.floor(Math.random() * 0x10000)
    .toString(16)
    .padStart(4, '0');
  return `${now.getUTCFullYear()}${p(now.getUTCMonth() + 1)}${p(now.getUTCDate())}-${p(now.getUTCHours())}${p(now.getUTCMinutes())}-${hex}`;
}

export const freshProblem = (topic: string): string | null =>
  isFixtureTopic(topic) ? null : `--fresh is for a fixture topic (commissions[key].fixtureTopics); ${topic} is not one`;

interface Ledger {
  outputs?: Record<string, { kind?: string; events?: { kind: string; id?: string }[] }>;
}

/** Move `scripts/<slug>/` (with its Shorts and its run folder) to `history/<run id>/`, record the previous outputs as
 *  superseded beside it, and leave a clean folder holding only `run/fresh.json`. */
export function archiveProduction(
  topic: string,
  storyId: string,
  root = ROOT,
  now = new Date(),
): { runId: string; archived: string | null } {
  const problem = freshProblem(topic);
  if (problem) throw new Refusal(problem);
  const dir = scriptDir(topic, storyId, root);
  const lock = readLock(runDir(topic, storyId, root));
  if (lock && alive(lock.pid))
    throw new Refusal(`a live run holds ${topic} ${storyId} (pid ${lock.pid}); not archived`);
  const previous = readJson<FreshRun>(join(runDir(topic, storyId, root), 'fresh.json'))?.runId ?? null;
  const runId = freshRunId(now);
  let archived: string | null = null;
  const hasProduction = existsSync(dir) && readdirSync(dir).some((f) => f !== RUN_DIR);
  if (hasProduction || (existsSync(dir) && readdirSync(join(dir, RUN_DIR)).some((f) => f !== 'fresh.json'))) {
    archived = join(topicDir(topic, root), HISTORY_DIR, runId);
    mkdirSync(join(topicDir(topic, root), HISTORY_DIR), { recursive: true });
    renameSync(dir, archived);
    const ledger = readJson<Ledger>(join(archived, 'publish.json'));
    const outputs = Object.fromEntries(
      Object.entries(ledger?.outputs ?? {}).map(([key, o]) => {
        const id = o.events?.find((e) => e.kind === 'uploaded')?.id;
        return [key, { status: 'superseded', kind: o.kind, ...(id && { id }) }];
      }),
    );
    writeJsonAtomic(join(archived, 'archived.json'), {
      story: storyId,
      runId,
      previous,
      archivedAt: now.toISOString(),
      outputs,
    });
  }
  mkdirSync(runDir(topic, storyId, root), { recursive: true });
  const fresh: FreshRun = { runId, at: now.toISOString(), previous };
  writeJsonAtomic(join(scriptDir(topic, storyId, root), FRESH_FILE), fresh);
  return { runId, archived };
}
